const allRuns = $input.all().map(i => i.json);

// The 9 expected workflows
const expectedWorkflows = [
  "HubSpot Lead Enrichment",
  "Shopify Order Confirmation",
  "Shopify to HubSpot Sync",
  "Airtable to Notion Sync",
  "Stripe Payment Fan-Out",
  "Google Calendar to Slack",
  "Spreadsheet Validation",
  "Canvas Deadline Aggregator",
  "Multi-Tenant Payment Notifications"
];

const rollup = {};

// 1. Initialize all workflows as stale with zero counts
for (const name of expectedWorkflows) {
  rollup[name] = { success: 0, failed: 0, partial: 0, stale: true };
}

// 2. Aggregate the actual run data
for (const run of allRuns) {
  if (!run || !run.workflow_name) continue; // Skip empty rows

  if (rollup[run.workflow_name]) {
    rollup[run.workflow_name].stale = false; // It ran!

    const status = (run.status || '').toLowerCase();

    if (status === 'failed' || status === 'error') {
      rollup[run.workflow_name].failed++;
    } else if (status === 'partial' || status === 'staged') {
      rollup[run.workflow_name].partial++;
    } else {
      rollup[run.workflow_name].success++;
    }
  }
}

return [{ json: rollup }];

